<style>
  .trust-badges {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    width: 100%;
    margin-bottom: 12px;
    padding: 6px 0 2px;
    color: #4e596f;
  }

  .trust-badges__item {
    display: flex;
    flex: 1 1 0;
    min-width: 0;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    gap: 4px;
    text-align: center;
  }

  .trust-badges__icon {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 18px;
  }

  .trust-badges__icon svg {
    height: 100%;
    width: auto;
    display: block;
  }

  .trust-badges__label {
    font-family: var(--font-family-base);
    font-weight: 500;
    font-size: var(--font-size-caption);
    line-height: 14px;
    color: #4e596f;
  }

  @media (max-width: 400px) {
    .trust-badges {
      margin-bottom: 10px;
      padding: 4px 0 2px;
    }

    .trust-badges__item {
      gap: 3px;
    }

    .trust-badges__icon {
      height: 16px;
    }

    .trust-badges__label {
      font-size: 10px;
      line-height: 13px;
    }
  }

  @media (max-width: 360px) {
    .trust-badges {
      margin-bottom: 8px;
    }

    .trust-badges__item {
      gap: 2px;
    }

    .trust-badges__icon {
      height: 14px;
    }

    .trust-badges__label {
      font-size: 9px;
      line-height: 12px;
    }
  }
</style>
